INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Brauche ich hier ein Kanban-Board?', 2, '[{"text": "Ja", "correct": true, "because": "Macht Arbeit sichtbar"}, {"text": "Nein", "correct": false, "because": "Kernwerkzeug für Übersicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft mir, den Workflow zu begrenzen?', 3, '[{"text": "WIP-Limits", "correct": true, "because": "Begrenzt parallele Aufgaben"}, {"text": "Kanban-Board", "correct": false, "because": "Zeigt Status, begrenzt nicht"}, {"text": "To-Do-Listen", "correct": false, "because": "Keine Begrenzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hilfsmittel fördern hier Übersichtlichkeit?', 5, '[{"text": "Kanban-Board", "correct": true, "because": "Visualisiert Workflow"}, {"text": "WIP-Limits", "correct": true, "because": "Verhindert Überlastung"}, {"text": "Unstrukturierte Listen", "correct": false, "because": "Wenig Übersicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kanban-Board zeigt den Status. b) WIP-Limits sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "WIP-Limits zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung dieser Werkzeuge?', 4, '[{"text": "Kanban-Board", "correct": false, "because": "Kern für Sichtbarkeit"}, {"text": "WIP-Limits", "correct": false, "because": "Begrenzung essenziell"}, {"text": "Unbegrenzte Aufgaben", "correct": true, "because": "WIP-Limits verhindern"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich ohne Board arbeite?', 2, '[{"text": "Nein", "correct": true, "because": "Board ist Standard"}, {"text": "Ja", "correct": false, "because": "Visualisierung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wähle ich für klare Statusübersicht?', 3, '[{"text": "Kanban-Board", "correct": true, "because": "Zeigt Fortschritt"}, {"text": "WIP-Limits", "correct": false, "because": "Begrenzt, zeigt nicht"}, {"text": "Excel-Tabellen", "correct": false, "because": "Weniger visuell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringen diese Hilfsmittel?', 5, '[{"text": "Transparenz", "correct": true, "because": "Board visualisiert"}, {"text": "Fokus", "correct": true, "because": "WIP-Limits begrenzen"}, {"text": "Chaos", "correct": false, "because": "Ordnung schaffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) WIP-Limits vermeiden Überlastung. b) Boards sind unwichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Boards essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Kanban-Board", "correct": false, "because": "Kern für Übersicht"}, {"text": "WIP-Limits", "correct": false, "because": "Schützt vor Überlast"}, {"text": "Endlose Aufgaben", "correct": true, "because": "WIP-Limits begrenzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind WIP-Limits hier optional?', 2, '[{"text": "Nein", "correct": true, "because": "Kernprinzip"}, {"text": "Ja", "correct": false, "because": "Begrenzung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werkzeuge unterstützen den Workflow?', 4, '[{"text": "Kanban-Board", "correct": true, "because": "Status sichtbar"}, {"text": "WIP-Limits", "correct": true, "because": "Fluss steuern"}, {"text": "Zufällige Notizen", "correct": false, "because": "Wenig Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich ohne Limits arbeite. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "WIP-Limits sind Standard"}, {"text": "Ja", "correct": false, "because": "Begrenzung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich mit diesen Tools?', 3, '[{"text": "Übersichtlichkeit", "correct": true, "because": "Board zeigt Status"}, {"text": "Unbegrenzte Arbeit", "correct": false, "because": "WIP-Limits verhindern"}, {"text": "Versteckte Aufgaben", "correct": false, "because": "Visualisierung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Boards visualisieren Arbeit. b) Limits erhöhen Chaos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Limits reduzieren Chaos"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Stärken haben diese Werkzeuge?', 5, '[{"text": "Klarheit", "correct": true, "because": "Board zeigt Fortschritt"}, {"text": "Effizienz", "correct": true, "because": "Limits fördern Fokus"}, {"text": "Unordnung", "correct": false, "because": "Struktur schaffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier unwichtig?', 3, '[{"text": "Kanban-Board", "correct": false, "because": "Kern der Visualisierung"}, {"text": "WIP-Limits", "correct": false, "because": "Begrenzung essenziell"}, {"text": "Unbegrenzte Aufgaben", "correct": true, "because": "Limits steuern"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich das Board weglassen?', 3, '[{"text": "Nein", "correct": true, "because": "Visualisierung nötig"}, {"text": "Ja", "correct": false, "because": "Board ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Limits hier Chaos fördern?', 2, '[{"text": "Nein", "correct": true, "because": "WIP-Limits ordnen"}, {"text": "Ja", "correct": false, "because": "Fokus schaffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug wähle ich für besseren Fokus?', 4, '[{"text": "WIP-Limits", "correct": true, "because": "Begrenzt parallele Arbeit"}, {"text": "Endlose Listen", "correct": false, "because": "Keine Begrenzung"}, {"text": "Versteckte Boards", "correct": false, "because": "Sichtbarkeit nötig"}]');
